                   tempWeights[2] == nullptr ? -1 : (int)tempWeights[2]->dims.size(),
                   tempWeights[2] == nullptr || tempWeights[2]->dims.size() < 1 ? -1 : tempWeights[2]->dims[0],
                   tempWeights[2] == nullptr || tempWeights[2]->dims.size() < 2 ? -1 : tempWeights[2]->dims[1]);
