using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public static class FileReadBench {
    public struct Result {
        public string Name;
        public int Threads;
        public int BlockKB;
        public double Seconds;
        public long Bytes;
        public long Reads;
        public long Checksum;
        public double MBps { get { return Bytes / 1048576.0 / Seconds; } }
        public double Iops { get { return Reads / Seconds; } }
    }

    public static Result Sequential(string path, long totalBytes, int blockBytes, int threads) {
        long len = new FileInfo(path).Length;
        long bytes = 0, reads = 0, checksum = 0;
        var sw = Stopwatch.StartNew();
        Task[] tasks = new Task[threads];
        long perThread = totalBytes / threads;
        long segment = len / threads;
        for (int t = 0; t < threads; t++) {
            int tid = t;
            tasks[t] = Task.Run(() => {
                byte[] buf = new byte[blockBytes];
                long localBytes = 0, localReads = 0, localChecksum = 0;
                long start = (segment * tid / blockBytes) * (long)blockBytes;
                using (var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, blockBytes, FileOptions.SequentialScan)) {
                    fs.Position = start;
                    while (localBytes < perThread) {
                        int want = (int)Math.Min(blockBytes, perThread - localBytes);
                        int n = fs.Read(buf, 0, want);
                        if (n <= 0) break;
                        localBytes += n;
                        localReads++;
                        localChecksum += buf[0];
                    }
                }
                Interlocked.Add(ref bytes, localBytes);
                Interlocked.Add(ref reads, localReads);
                Interlocked.Add(ref checksum, localChecksum);
            });
        }
        Task.WaitAll(tasks);
        sw.Stop();
        return new Result { Name = "sequential", Threads = threads, BlockKB = blockBytes / 1024, Seconds = sw.Elapsed.TotalSeconds, Bytes = bytes, Reads = reads, Checksum = checksum };
    }

    public static Result RandomRead(string path, int seconds, int blockBytes, int threads) {
        long len = new FileInfo(path).Length;
        long maxOffset = len - blockBytes;
        long align = 4096;
        long bytes = 0, reads = 0, checksum = 0;
        var startGate = new ManualResetEventSlim(false);
        var sw = new Stopwatch();
        Task[] tasks = new Task[threads];
        for (int t = 0; t < threads; t++) {
            int tid = t;
            tasks[t] = Task.Run(() => {
                byte[] buf = new byte[blockBytes];
                var rng = new Random(1234 + tid * 7919);
                long localBytes = 0, localReads = 0, localChecksum = 0;
                startGate.Wait();
                using (var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, blockBytes, FileOptions.RandomAccess)) {
                    while (sw.Elapsed.TotalSeconds < seconds) {
                        double r = rng.NextDouble();
                        long off = (long)(r * maxOffset);
                        off = (off / align) * align;
                        fs.Position = off;
                        int got = 0;
                        while (got < blockBytes) {
                            int n = fs.Read(buf, got, blockBytes - got);
                            if (n <= 0) break;
                            got += n;
                        }
                        if (got <= 0) break;
                        localBytes += got;
                        localReads++;
                        localChecksum += buf[0];
                    }
                }
                Interlocked.Add(ref bytes, localBytes);
                Interlocked.Add(ref reads, localReads);
                Interlocked.Add(ref checksum, localChecksum);
            });
        }
        sw.Start();
        startGate.Set();
        Task.WaitAll(tasks);
        sw.Stop();
        return new Result { Name = "random", Threads = threads, BlockKB = blockBytes / 1024, Seconds = sw.Elapsed.TotalSeconds, Bytes = bytes, Reads = reads, Checksum = checksum };
    }

    public static void Print(Result r) {
        Console.WriteLine("{0}, threads={1}, blockKB={2}, sec={3:F2}, MBps={4:F1}, IOPS={5:F1}, reads={6}, checksum={7}", r.Name, r.Threads, r.BlockKB, r.Seconds, r.MBps, r.Iops, r.Reads, r.Checksum);
    }
}
