    const uint FILE_FLAG_RANDOM_ACCESS = 0x10000000;
    const uint MEM_COMMIT = 0x1000;
    const uint MEM_RESERVE = 0x2000;
    const uint PAGE_READWRITE = 0x04;

    [DllImport("kernel32.dll", SetLastError=true, CharSet=CharSet.Unicode)]
    static extern SafeFileHandle CreateFileW(string lpFileName, uint dwDesiredAccess, uint dwShareMode, IntPtr lpSecurityAttributes, uint dwCreationDisposition, uint dwFlagsAndAttributes, IntPtr hTemplateFile);

    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool ReadFile(SafeFileHandle hFile, IntPtr lpBuffer, int nNumberOfBytesToRead, out int lpNumberOfBytesRead, IntPtr lpOverlapped);

    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool SetFilePointerEx(SafeFileHandle hFile, long liDistanceToMove, out long lpNewFilePointer, uint dwMoveMethod);

    [DllImport("kernel32.dll", SetLastError=true)]
    static extern IntPtr VirtualAlloc(IntPtr lpAddress, UIntPtr dwSize, uint flAllocationType, uint flProtect);

    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool VirtualFree(IntPtr lpAddress, UIntPtr dwSize, uint dwFreeType);

    static SafeFileHandle Open(string path, bool random) {
        uint flags = FILE_FLAG_NO_BUFFERING | (random ? FILE_FLAG_RANDOM_ACCESS : FILE_FLAG_SEQUENTIAL_SCAN);
        var h = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, IntPtr.Zero, OPEN_EXISTING, flags, IntPtr.Zero);
        if (h.IsInvalid) throw new Win32Exception(Marshal.GetLastWin32Error());
        return h;
    }

    static IntPtr Alloc(int bytes) {
        var p = VirtualAlloc(IntPtr.Zero, (UIntPtr)bytes, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
        if (p == IntPtr.Zero) throw new Win32Exception(Marshal.GetLastWin32Error());
        return p;
    }

    public struct Result {
        public string Name;
        public int Threads;
        public int BlockKB;
        public double Seconds;
        public long Bytes;
        public long Reads;
        public double MBps { get { return Bytes / 1048576.0 / Seconds; } }
        public double Iops { get { return Reads / Seconds; } }
    }

    public static Result Sequential(string path, long totalBytes, int blockBytes) {
        long bytes = 0, reads = 0;
        var sw = Stopwatch.StartNew();
        using (var h = Open(path, false)) {
            IntPtr buf = Alloc(blockBytes);
            try {
                long pos;
                if (!SetFilePointerEx(h, 0, out pos, 0)) throw new Win32Exception(Marshal.GetLastWin32Error());
                while (bytes < totalBytes) {
                    int want = (int)Math.Min(blockBytes, totalBytes - bytes);
                    int got;
                    if (!ReadFile(h, buf, want, out got, IntPtr.Zero)) throw new Win32Exception(Marshal.GetLastWin32Error());
                    if (got <= 0) break;
                    bytes += got;
                    reads++;
                }
            } finally {
                VirtualFree(buf, UIntPtr.Zero, 0x8000);
            }
        }
        sw.Stop();
        return new Result { Name = "unbuffered sequential", Threads = 1, BlockKB = blockBytes / 1024, Seconds = sw.Elapsed.TotalSeconds, Bytes = bytes, Reads = reads };
    }

    public static Result RandomRead(string path, int seconds, int blockBytes, int threads) {
        long len = new FileInfo(path).Length;
        long maxOffset = len - blockBytes;
        long bytes = 0, reads = 0;
        var startGate = new ManualResetEventSlim(false);
        var sw = new Stopwatch();
        Task[] tasks = new Task[threads];
        for (int t = 0; t < threads; t++) {
            int tid = t;
            tasks[t] = Task.Run(() => {
                long localBytes = 0, localReads = 0;
                var rng = new Random(20260510 + tid * 104729);
                using (var h = Open(path, true)) {
                    IntPtr buf = Alloc(blockBytes);
                    try {
                        startGate.Wait();
                        while (sw.Elapsed.TotalSeconds < seconds) {
                            long off = (long)(rng.NextDouble() * maxOffset);
                            off = (off / 4096) * 4096;
                            long pos;
                            if (!SetFilePointerEx(h, off, out pos, 0)) throw new Win32Exception(Marshal.GetLastWin32Error());
                            int got;
                            if (!ReadFile(h, buf, blockBytes, out got, IntPtr.Zero)) throw new Win32Exception(Marshal.GetLastWin32Error());
                            if (got <= 0) break;
                            localBytes += got;
                            localReads++;
                        }
                    } finally {
                        VirtualFree(buf, UIntPtr.Zero, 0x8000);
                    }
                }
                Interlocked.Add(ref bytes, localBytes);
                Interlocked.Add(ref reads, localReads);
            });
        }
        sw.Start();
        startGate.Set();
        Task.WaitAll(tasks);
        sw.Stop();
        return new Result { Name = "unbuffered random", Threads = threads, BlockKB = blockBytes / 1024, Seconds = sw.Elapsed.TotalSeconds, Bytes = bytes, Reads = reads };
    }

    public static void Print(Result r) {
        Console.WriteLine("{0}, threads={1}, blockKB={2}, sec={3:F2}, MBps={4:F1}, IOPS={5:F1}, reads={6}", r.Name, r.Threads, r.BlockKB, r.Seconds, r.MBps, r.Iops, r.Reads);
    }
