    static std::wstring UTF8ToWidePath(const std::string &path) {
#if defined(_WIN32) || defined(_WIN64)
        std::wstring widePath = MultiByteToWidePath(path, CP_UTF8);
        if (widePath.empty() && !path.empty()) {
            widePath = MultiByteToWidePath(path, CP_ACP);
        }
        return widePath;
