    static FILE *FastllmFileOpen(const std::string &path, const char *mode) {
#if defined(_WIN32) || defined(_WIN64)
        std::wstring widePath = UTF8ToWidePath(path);
        std::wstring wideMode(mode, mode + strlen(mode));
        return _wfopen(widePath.c_str(), wideMode.c_str());
#else
        return fopen(path.c_str(), mode);
#endif
    }

    static int FastllmOpenReadOnlyBinary(const std::string &path) {
