    uint64_t Data::Count(int i) const {
        if (this->dataType == DataType::DATA_GGUF_FORMAT && i == 0) {
            return ggml_nbytes((ggml_tensor*)this->ggmlTensor);
        }
        if (i >= this->dims.size()) {
