    void Data::Resize(const std::vector<int> &dims) {
        std::vector <int> oldDims = this->dims;
        uint64_t oldCount = 1, newCount = 1;
        for (int v : oldDims) {
            oldCount *= v;
        }
        for (int v : dims) {
            newCount *= v;
        }
        this->dims = dims;
        this->UpdateUnitSize();

        if (this->dataType == DATA_GGUF_FORMAT) {
            std::vector <int> cur = dims;
            std::reverse(cur.begin(), cur.end());

