                this->ggmlTensor = new ggml_tensor();
            }
            ggml_tensor* tensor = (ggml_tensor*)this->ggmlTensor;
            tensor->type = (ggml_type)this->ggmlType;
            for (int j = 0; j < GGML_MAX_DIMS; j++) {
                tensor->ne[j] = 1;
                if (j < cur.size()) {
                    tensor->ne[j] = cur[j];
                }
            }

            {
                tensor->type = (ggml_type)this->ggmlType;
