{"command":"@'
import struct
from pathlib import Path

path = Path('cyberneurova-DeepSeek-V4-Flash-abliterated-Q8_0.gguf')
with path.open('rb') as f:
    def read(n):
        b = f.read(n)
        if len(b) != n:
            raise EOFError
        return b
    magic = read(4)
    if magic != b'GGUF':
        raise SystemExit(f'bad magic: {magic!r}')
    version, = struct.unpack('<I', read(4))
    tensor_count, = struct.unpack('<Q', read(8))
    kv_count, = struct.unpack('<Q', read(8))
    print('version', version, 'tensor_count', tensor_count, 'kv_count', kv_count)

    def read_str():
        n, = struct.unpack('<Q', read(8))
        return read(n).decode('utf-8', errors='replace')

    def read_scalar(t):
        fmts = {
            0: '<B', 1: '<b', 2: '<H', 3: '<h', 4: '<I', 5: '<i',
            6: '<f', 7: '<?', 10: '<Q', 11: '<q', 12: '<d',
        }
        if t == 8:
            return read_str()
        fmt = fmts.get(t)
        if fmt is None:
            raise ValueError(f'unsupported scalar type {t}')
        return struct.unpack(fmt, read(struct.calcsize(fmt)))[0]

    def skip_scalar(t):
        sizes = {0:1,1:1,2:2,3:2,4:4,5:4,6:4,7:1,10:8,11:8,12:8}
        if t == 8:
            n, = struct.unpack('<Q', read(8)); read(n); return
        if t in sizes:
            read(sizes[t]); return
        raise ValueError(f'unsupported skip type {t}')

    meta = {}
    for _ in range(kv_count):
        key = read_str()
        typ, = struct.unpack('<I', read(4))
        if typ == 9:
            elem_typ, = struct.unpack('<I', read(4))
            n, = struct.unpack('<Q', read(8))
            vals = []
            keep = n <= 16 and any(s in key.lower() for s in ('expert','moe','deepseek','block','feed','ffn'))
            for i in range(n):
                if keep:
                    vals.append(read_scalar(elem_typ))
                else:
                    skip_scalar(elem_typ)
            val = vals if keep else f'<array type={elem_typ} len={n}>'
        else:
            val = read_scalar(typ)
        meta[key] = val

    for key in sorted(meta):
        lk = key.lower()
        if any(s in lk for s in ('expert', 'moe', 'routed', 'ffn', 'feed_forward', 'deepseek')):
            print(f'{key} = {meta[key]!r}')
