        if (std::getenv("FASTLLM_DEBUG_DISK_MOE") != nullptr) {
            printf("[fastllm-disk-moe] cpu-merge-done\n");
            fflush(stdout);
        }
        if (promoteInput) {
            ConvertFloat32ToOutput(promotedOutput, output, originalOutputType);
