    static std::wstring MultiByteToWidePath(const std::string &path, UINT codePage) {
        if (path.empty()) {
            return std::wstring();
        }
        int len = MultiByteToWideChar(codePage, 0, path.c_str(), -1, nullptr, 0);
        if (len <= 0) {
            return std::wstring();
        }
        std::wstring wide(len, L'\0');
        MultiByteToWideChar(codePage, 0, path.c_str(), -1, &wide[0], len);
        if (!wide.empty() && wide.back() == L'\0') {
            wide.pop_back();
        }
        return wide;
    }
#endif

    static std::wstring UTF8ToWidePath(const std::string &path) {
#if defined(_WIN32) || defined(_WIN64)
