        this->isLinearAttention = ori.isLinearAttention;
        this->cacheUid = ori.cacheUid;
        this->dataDevice = ori.dataDevice;
        this->tpLayout = ori.tpLayout;
        this->tpAxis = ori.tpAxis;
        this->tpGlobalDims = ori.tpGlobalDims;
